def dqn_target(reward, gamma, next_q, done=False):
    """Target for one transition, built from the frozen target network."""
    return reward + gamma * max(next_q)

tests_py:
def test_known_target():
    assert abs(solution.dqn_target(1.0, 0.9, [0.8]) - 1.72) < 1e-12

def test_takes_best_next():
    assert solution.dqn_target(0.0, 1.0, [0.5, 2.0]) == 2.0

def test_terminal_stops():
    assert solution.dqn_target(1.0, 0.9, [5.0, 7.0], True) == 1.0

def test_terminal_empty_next_q():
    assert solution.dqn_target(3.0, 0.9, [], done=True) == 3.0

def test_zero_gamma():
    assert solution.dqn_target(2.0, 0.0, [100.0]) == 2.0

def test_empty_nonterminal_raises():
    try:
        solution.dqn_target(1.0, 0.9, [])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.dqn_target(1, 0.9, [1]), float)
